const LAYER_NAMES = {
  jung: 'Jung', freud: 'Freud', sales: 'Sales 101',
  seo: 'SEO', aiseo: 'AI-SEO', platform: 'Platform'
};

const ARCHETYPES = {
  ruler:     { tone: 'sovereign authority · long sentences · no apology',          keywords: ['control','authority','legacy','lead','power','own','command','decide'] },
  sage:      { tone: 'precise · undefended · expertise without performance',        keywords: ['truth','understand','clear','principle','know','wisdom','insight','depth'] },
  hero:      { tone: 'edge · stakes · forward velocity',                            keywords: ['win','beat','conquer','edge','prove','dominate','crush','breakthrough'] },
  caregiver: { tone: 'safety · warmth · the work done for you',                     keywords: ['care','help','protect','safe','support','gentle','hold','tend'] },
  outlaw:    { tone: 'disruption · permission to break · unembarrassed',            keywords: ['break','rebel','disrupt','unfuck','burn','quit','escape','rules'] },
  lover:     { tone: 'beauty · texture · intimacy · sensory',                       keywords: ['love','beautiful','intimate','deep','feel','desire','touch','heart'] },
  seeker:    { tone: 'horizon · freedom · what\'s next',                            keywords: ['journey','explore','find','discover','seek','quest','road','beyond'] },
  creator:   { tone: 'original · made · yours alone',                               keywords: ['make','build','create','design','craft','original','vision','imagine'] }
};

const SHADOW_WORDS = {
  jung_strong: ['shadow','disowned','projection','archetype','persona','integration','unconscious','depth','soul'],
  freud_strong: ['actually want','underneath','beneath','really','admit','denied','suppress','wish','crave','repress'],
  sales_strong: ['proven','results','customers','case','client','testimonial','data','%','x ','increase','within','days'],
  weak_words: ['really','very','just','quite','perhaps','maybe','probably','might','some','many','various','seems','feel like','i think','believe','hope'],
  hedges: ['it could be argued','one might say','in some sense','arguably','potentially','typically','generally','tends to','sort of','kind of'],
  filler: ['that is','in order to','due to the fact','at this point in time','for all intents and purposes','needless to say'],
  jargon_warn: ['leverage','synergy','disrupt','ideate','solutioning','holistic','ecosystem','best-in-class','game-changer','paradigm shift']
};

const SALES_HOOK_PATTERNS = [
  /^(stop|never|imagine|what if|here'?s|the truth about|why|how to|after|before|when)/i,
  /^[A-Z][^.!?]+\?/, // opening question
  /^[A-Z][^.!?]{0,90}[.!]$/ // crisp first sentence
];

const CTA_PATTERNS = [
  /\b(get|start|join|try|download|book|claim|grab|buy|reserve|subscribe|sign up|read more|learn more|find out|begin|enter|see|watch)\b/i,
  /→|->|»/,
  /\b(free|trial|now|today|here)\b/i
];

/* ── THE ENGINE · 6 layer analysis ─────────────────────────────────── */

function detectArchetype(text) {
  const lower = text.toLowerCase();
  let best = 'sage', bestScore = -1;
  for (const [arch, info] of Object.entries(ARCHETYPES)) {
    let score = 0;
    for (const kw of info.keywords) {
      const m = lower.match(new RegExp('\\b' + kw + '\\b', 'g'));
      if (m) score += m.length;
    }
    if (score > bestScore) { bestScore = score; best = arch; }
  }
  return best;
}

/* ── LAYER 1 · JUNG  ─────────────────────────────────────────────── */
function scoreJung(text, audience) {
  const lower = text.toLowerCase();
  const arch = ARCHETYPES[audience] || ARCHETYPES.sage;
  let score = 0;
  const notes = [];

  // archetype voice presence
  let archHits = 0;
  for (const kw of arch.keywords) {
    if (lower.includes(kw)) archHits++;
  }
  if (archHits >= 3) { score += 30; notes.push(`✓ Strong ${audience} archetype voice (${archHits} signals)`); }
  else if (archHits >= 1) { score += 15; notes.push(`◔ Light ${audience} archetype presence (${archHits} signal${archHits>1?'s':''})`); }
  else { notes.push(`✗ No clear ${audience} archetype voice — copy reads as generic`); }

  // shadow surfacing
  let shadowHits = 0;
  for (const w of SHADOW_WORDS.jung_strong) {
    if (lower.includes(w)) shadowHits++;
  }
  if (shadowHits >= 2) { score += 25; notes.push('✓ Touches shadow / unconscious material directly'); }
  else { notes.push('◔ Surface only — doesn\'t name what they\'re avoiding'); }

  // depth markers
  const longSents = (text.match(/[^.!?]{80,}[.!?]/g) || []).length;
  if (longSents >= 2) { score += 15; notes.push('✓ At least two sentences carrying real weight (length-as-depth)'); }

  // emotional vocab (not just adjectives — verbs of feeling)
  if (/\b(grieve|long|crave|fear|ache|burn|hunger|rage|tender|yearn)\b/i.test(text)) {
    score += 15;
    notes.push('✓ Uses verbs of feeling, not adjectives — body-level resonance');
  }

  // shadow voice mirroring
  if (/\bvoice (inside|in your head)\b|\byou (already )?know\b|\bwhat you (refuse|disown|won't admit)\b/i.test(text)) {
    score += 15;
    notes.push('✓ Mirrors the inner voice — high-trust pattern');
  }

  return { score: Math.min(100, score), notes };
}

/* ── LAYER 2 · FREUD  ────────────────────────────────────────────── */
function scoreFreud(text) {
  const lower = text.toLowerCase();
  let score = 0;
  const notes = [];

  // names id directly
  let idHits = 0;
  for (const w of SHADOW_WORDS.freud_strong) {
    if (lower.includes(w)) idHits++;
  }
  if (idHits >= 2) { score += 30; notes.push('✓ Names the deeper want directly (id-level)'); }
  else if (idHits >= 1) { score += 15; notes.push('◔ One id-level cue — could go deeper'); }
  else { notes.push('✗ Stays in ego — never punctures the rationalization'); }

  // gap between id/ego/superego
  if (/\byou (say|claim|tell yourself|pretend)\b/i.test(text)) { score += 20; notes.push('✓ Names the gap between what they say and what they want'); }
  if (/\b(but )?underneath|behind that|actually|the real|truth is\b/i.test(text)) { score += 20; notes.push('✓ Pulls back the surface explanation'); }

  // defence puncture
  if (/\b(stop pretending|let'?s be honest|the lie is|the story you tell|the version of you)\b/i.test(text)) {
    score += 20;
    notes.push('✓ Punctures defence directly — high-impact move');
  }

  // moralized want (superego)
  if (/\byou should\b|\beveryone says\b|\bthe right thing\b/i.test(lower)) {
    score += 10;
    notes.push('◔ Surfaces the superego — adds the third Freud axis');
  }

  return { score: Math.min(100, score), notes };
}

/* ── LAYER 3 · SALES 101  ────────────────────────────────────────── */
function scoreSales(text, task) {
  const lower = text.toLowerCase();
  let score = 0;
  const notes = [];
  const firstSentence = (text.match(/^[\s\S]+?[.!?](?:\s|$)/) || [''])[0].trim();

  // hook
  let hooked = false;
  for (const p of SALES_HOOK_PATTERNS) {
    if (p.test(firstSentence)) { hooked = true; break; }
  }
  if (hooked) { score += 20; notes.push('✓ Opens with a hook pattern'); }
  else { notes.push('✗ No hook in the first sentence · re-write opener'); }

  // specificity — numbers, dates, names
  const numbers = (text.match(/\b\d[\d,.]*\b/g) || []).length;
  const named = (text.match(/\b[A-Z][a-z]+\s[A-Z][a-z]+\b/g) || []).length;
  if (numbers >= 3) { score += 15; notes.push(`✓ Specific (${numbers} numeric anchors)`); }
  else if (numbers >= 1) { score += 7; notes.push(`◔ Some specificity (${numbers} number${numbers>1?'s':''}) — could anchor more`); }
  else { notes.push('✗ No numeric specificity · adds friction to belief'); }
  if (named >= 1) { score += 10; notes.push('✓ Named entities cited (people / brands)'); }

  // stakes named
  if (/\b(cost|risk|losing|miss|too late|while you|every (day|month|year))\b/i.test(text)) {
    score += 15;
    notes.push('✓ Stakes named — what happens if they don\'t');
  } else {
    notes.push('◔ No stakes named — reader has no urgency');
  }

  // social proof
  if (/\b(\d+ (people|users|customers|clients)|case stud|testimonial|\bquot|"[^"]+ [^"]+"|\d+x\b|\d+%)/i.test(text)) {
    score += 15;
    notes.push('✓ Proof element present');
  } else {
    notes.push('✗ No proof — every claim survives without backing');
  }

  // CTA
  let ctaPresent = false;
  for (const p of CTA_PATTERNS) {
    if (p.test(text)) { ctaPresent = true; break; }
  }
  if (task !== 'blog-post' && task !== 'dev-docs') {
    if (ctaPresent) { score += 15; notes.push('✓ CTA detected'); }
    else { notes.push('✗ No clear CTA · sales-class copy needs a next step'); }
  }

  // weak / hedge words
  let weakHits = 0;
  for (const w of SHADOW_WORDS.weak_words) {
    const m = lower.match(new RegExp('\\b' + w + '\\b', 'g'));
    if (m) weakHits += m.length;
  }
  if (weakHits > 5) { score -= 10; notes.push(`✗ ${weakHits} weak / hedge words ("really", "just", "maybe"…) — strip them`); }

  // earned urgency vs fake urgency
  if (/\bact now|hurry|don'?t miss|limited time|\d+ (hours?|spots?|seats?) left\b/i.test(text)) {
    if (!/\d/.test(text)) { notes.push('◔ Urgency words present but unearned — needs a specific number / deadline'); }
    else { score += 10; notes.push('✓ Urgency with a specific anchor'); }
  }

  return { score: Math.max(0, Math.min(100, score)), notes };
}

/* ── LAYER 4 · SEO  ──────────────────────────────────────────────── */
function scoreSeo(text, task) {
  let score = 0;
  const notes = [];
  const lower = text.toLowerCase();

  // headers — markdown # or HTML h tags or detected structure
  const headers = (text.match(/^#{1,6} |<h[1-6]/gm) || []).length;
  if (headers >= 2) { score += 25; notes.push(`✓ Heading structure (${headers} headings detected)`); }
  else if (task === 'blog-post' || task === 'readme') { notes.push('✗ No headings · long-form needs H1/H2/H3 skim structure'); }

  // density — find probable primary keyword by repetition
  const words = lower.match(/[a-z]{4,}/g) || [];
  const freq = {};
  const stops = ['that','this','with','from','your','have','will','what','they','their','about','which','there','would','could','should','because','where','these','than','when','only','also'];
  for (const w of words) { if (!stops.includes(w)) freq[w] = (freq[w]||0)+1; }
  const top = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,3);
  if (top.length && top[0][1] >= 3) { score += 15; notes.push(`✓ Likely primary keyword cluster: ${top.map(t=>t[0]).join(' · ')}`); }
  else { notes.push('◔ No clear keyword cluster — search engines can\'t place the page'); }

  // intent signals
  if (/\b(how to|what is|why|guide|tutorial|review|vs\.?)\b/i.test(text)) {
    score += 15;
    notes.push('✓ Search intent signal present (how-to / what-is / vs)');
  }

  // length
  const wordCount = words.length;
  if (task === 'blog-post') {
    if (wordCount >= 1200) { score += 20; notes.push(`✓ Substantial length (${wordCount} words)`); }
    else { notes.push(`◔ Short for blog (${wordCount} words) — long-form ranks better for most topics`); }
  } else if (task === 'readme') {
    if (wordCount >= 400) { score += 15; }
  } else {
    if (wordCount >= 80) score += 15;
  }

  // links
  if (/\[[^\]]+\]\([^)]+\)|<a href|https?:\/\//.test(text)) {
    score += 10;
    notes.push('✓ Contains links');
  }

  // meta description shape — first sentence under 160 chars
  const firstSentence = (text.match(/^[\s\S]+?[.!?](?:\s|$)/) || [''])[0].trim();
  if (firstSentence.length > 0 && firstSentence.length <= 160 && task !== 'twitter') {
    score += 10;
    notes.push('✓ Opener works as meta description (≤160 chars)');
  }

  return { score: Math.min(100, score), notes };
}

/* ── LAYER 5 · AI-SEO / GEO / AEO  ───────────────────────────────── */
function scoreAiseo(text) {
  let score = 0;
  const notes = [];

  // lists & tables — LLM extraction loves these
  const lists = (text.match(/^\s*[-*•]\s|^\s*\d+\.\s/gm) || []).length;
  const tables = (text.match(/\|.*\|/g) || []).length;
  if (lists >= 3) { score += 20; notes.push(`✓ List structure (${lists} items) — LLMs extract these`); }
  if (tables >= 2) { score += 15; notes.push(`✓ Table-shaped content — high-citation format`); }
  if (lists === 0 && tables === 0) { notes.push('✗ No lists or tables · LLMs will struggle to cite extractable facts'); }

  // attributable claims
  if (/\baccording to\b|\bper\s+[A-Z]|\b(study|report|paper|research) by\b|\bsource:/i.test(text)) {
    score += 20;
    notes.push('✓ Attributable claims present');
  } else {
    notes.push('◔ No "according to X" attributions — LLMs prefer cited claims');
  }

  // named entities
  const propers = (text.match(/\b[A-Z][a-z]+(?:\s[A-Z][a-z]+){0,2}\b/g) || []).filter(s => !['The','This','That','These','I','You','We','They','It','But','And'].includes(s));
  if (propers.length >= 5) { score += 15; notes.push(`✓ Entity density (${propers.length} named entities)`); }
  else if (propers.length >= 2) { score += 8; }
  else { notes.push('◔ Few named entities — LLMs surface entity-rich pages first'); }

  // recency
  if (/\b20(2[3-9]|3\d)\b|\bas of\b|\b(this|last) (year|month|week)\b|\brecently\b/i.test(text)) {
    score += 10;
    notes.push('✓ Recency signals present');
  }

  // expertise / methodology
  if (/\b(method|approach|framework|criteria|process|step \d|first\b.*\bsecond|we (tested|measured|surveyed))\b/i.test(text)) {
    score += 15;
    notes.push('✓ Methodology / framework shown — expertise marker');
  }

  // question-shape (AEO answers questions)
  const questions = (text.match(/[^.!?]*\?/g) || []).length;
  if (questions >= 2) { score += 10; notes.push(`✓ Q-shape structure (${questions} questions) — AEO friendly`); }

  // semantic clarity (not stuffed)
  const wordsAll = (text.toLowerCase().match(/[a-z]+/g) || []);
  const unique = new Set(wordsAll);
  const ratio = unique.size / Math.max(1, wordsAll.length);
  if (ratio > 0.55) { score += 5; notes.push('✓ High lexical diversity — not stuffed'); }
  else if (ratio < 0.40) { notes.push('✗ Low lexical diversity — reads as stuffed / repetitive'); }

  return { score: Math.min(100, score), notes };
}

/* ── LAYER 6 · PLATFORM FIT  ─────────────────────────────────────── */
function scorePlatform(text, task) {
  let score = 50; // start neutral
  const notes = [];
  const wordCount = (text.match(/\S+/g) || []).length;
  const chars = text.length;
  const firstSentence = (text.match(/^[\s\S]+?[.!?](?:\s|$)/) || [''])[0].trim();
  const firstWords = (firstSentence.match(/\S+/g) || []).slice(0, 7).join(' ');

  switch (task) {
    case 'linkedin':
      if (chars > 1300 && chars < 2000) { score += 25; notes.push('✓ LinkedIn sweet spot length'); }
      else if (chars > 3000) { score -= 15; notes.push('✗ Too long for LinkedIn — cuts off mid-flow'); }
      else if (chars < 600) { score -= 5; notes.push('◔ Short for LinkedIn — leaves engagement on the table'); }
      const lineBreaks = (text.match(/\n\s*\n/g) || []).length;
      if (lineBreaks >= 4) { score += 15; notes.push('✓ Plenty of line breaks · scan-friendly'); }
      else { score -= 10; notes.push('✗ Not enough line breaks — LinkedIn copy without breaks dies'); }
      const hashtags = (text.match(/#\w+/g) || []).length;
      if (hashtags > 5) { score -= 15; notes.push('✗ Too many hashtags · reads spammy'); }
      else if (hashtags >= 1 && hashtags <= 4) { score += 5; }
      break;
    case 'twitter':
      if (chars > 280) { score -= 25; notes.push('✗ Over 280 chars — split into thread or trim'); }
      else if (chars > 230) { score += 10; notes.push('✓ Uses the full canvas'); }
      if (/^(hot take|unpopular|nobody|i've been|the most|here'?s)/i.test(firstSentence)) { score += 15; notes.push('✓ Twitter hook pattern detected'); }
      break;
    case 'email':
      const subjectLine = firstSentence;
      if (subjectLine.length > 50) { score -= 15; notes.push('✗ Likely subject line over 50 chars — gets truncated in inboxes'); }
      else { score += 15; notes.push('✓ Opener fits as subject line (<50 chars)'); }
      break;
    case 'landing':
      if (firstSentence.length > 0 && firstSentence.length <= 90) { score += 20; notes.push('✓ Tight headline'); }
      else { score -= 10; notes.push('◔ Headline runs long — hero copy needs to fit above fold'); }
      break;
    case 'readme':
      const codeBlocks = (text.match(/```/g) || []).length / 2;
      if (codeBlocks >= 1) { score += 15; notes.push(`✓ Code blocks present (${codeBlocks})`); }
      else { score -= 10; notes.push('◔ No code blocks — dev README without code lacks utility'); }
      if (/^#\s|^##\s/m.test(text)) { score += 10; notes.push('✓ Markdown structure'); }
      break;
    case 'sales-page':
    case 'blog-post':
    case 'client-deliverable':
      if (wordCount >= 300) score += 15;
      if (firstSentence.length < 90) score += 10;
      break;
  }

  // jargon penalty (cross-platform)
  let jargonHits = 0;
  for (const j of SHADOW_WORDS.jargon_warn) {
    if (text.toLowerCase().includes(j)) jargonHits++;
  }
  if (jargonHits >= 2) { score -= 15; notes.push(`✗ ${jargonHits} jargon words ("synergy", "leverage", "disrupt"…)`); }

  return { score: Math.max(0, Math.min(100, score)), notes };
}

/* ── COLLECT FINDINGS · top 6 across all layers, weighted ─────────── */

function collectFindings(text, task, audience, scores, findings, weights) {
  // verdict for each layer based on weight
  for (const k of Object.keys(scores)) {
    const w = weights[k];
    if (w === 0) continue;
    const s = scores[k].score;
    const verdict = s >= 75 ? 'good' : s >= 50 ? 'ok' : s >= 30 ? 'warn' : 'bad';
    const headline = {
      good: 'CLEAR · ships',
      ok: 'WORKS · could go deeper',
      warn: 'WEAK · needs rewrite',
      bad: 'FAILS · don\'t ship'
    }[verdict];
    const layerNotes = scores[k].notes;
    const top3 = layerNotes.slice(0, 4);
    findings.push({
      layer: LAYER_NAMES[k],
      verdict, headline,
      score: s, weight: w,
      notes: top3
    });
  }
  // sort by weight × shortfall (so most important + most broken floats up)
  findings.sort((a, b) => (b.weight * (100 - b.score)) - (a.weight * (100 - a.score)));
}


/* ── THE GATE · the whole reading, shared by the page and the skill script ── */

// One archetype, six layer scores, the findings and the weighted gate score for a piece of copy.
function gate(text, task, aud) {
  const weights = WEIGHTS[task];

  // ── detect dominant archetype if auto ──
  const detected = detectArchetype(text);
  const audience = aud === 'auto' ? detected : aud;

  // ── run each layer ──
  const scores = {
    jung:     scoreJung(text, audience),
    freud:    scoreFreud(text),
    sales:    scoreSales(text, task),
    seo:      scoreSeo(text, task),
    aiseo:    scoreAiseo(text),
    platform: scorePlatform(text, task)
  };
  const findings = [];
  collectFindings(text, task, audience, scores, findings, weights);

  // ── weighted total ──
  let weighted = 0, total = 0;
  for (const k of Object.keys(weights)) {
    if (weights[k] > 0) {
      weighted += scores[k].score * weights[k];
      total += weights[k];
    }
  }
  const gateScore = Math.round(weighted / total);
  return { task, audience, detected, weights, scores, findings, gateScore, text };
}

function rewriteMove(layer) {
  let move = '';
  if (layer === 'Sales 101') move = 'add a specific numeric anchor + named stakes + a clear next step.';
  else if (layer === 'Jung') move = 'name the archetypal voice you\'re speaking from and surface the shadow before they do.';
  else if (layer === 'Freud') move = 'puncture one rationalization · name what they actually want underneath the story.';
  else if (layer === 'SEO') move = 'add H1/H2 structure with the primary keyword and 2-3 semantic neighbours.';
  else if (layer === 'AI-SEO') move = 'add a list or table, an attributable claim ("according to X"), and recency signals.';
  else if (layer === 'Platform') move = 'fit the platform native conventions (length, line breaks, hook position).';
  return move;
}

// The rewrite priorities: the three weakest weighted layers that are failing or weak, with the move for each.
function rewritePriorities(r) {
  const failing = r.findings.filter(f => f.verdict === 'bad' || f.verdict === 'warn').slice(0, 3);
  if (failing.length === 0) return null;
  return {
    layersClear: Object.values(r.scores).filter(s => s.score >= 60).length,
    priorities: failing.map(f => ({ layer: f.layer, weight: f.weight, move: rewriteMove(f.layer) }))
  };
}
export { VERSION, WEIGHTS, LAYER_NAMES, ARCHETYPES, SHADOW_WORDS, SALES_HOOK_PATTERNS, CTA_PATTERNS, detectArchetype, scoreJung, scoreFreud, scoreSales, scoreSeo, scoreAiseo, scorePlatform, collectFindings, gate, rewriteMove, rewritePriorities };
